style.css:
@-moz-document domain("lotro-wiki.com") {
:root {
    --bg: #1b1e23;
    --bg-elevated: #22262c;
    --bg-input: #2a2f36;
    --text: #d8dee4;
    --text-muted: #9aa4b0;
    --link: #6fb3f2;
    --link-visited: #b38ff2;
    --border: #3a3f47;
  }

  html, body {
    background: var(--bg) !important;
    color: var(--text) !important;
  }

  #content, .mw-body, #bodyContent, .mw-body-content,
  .vector-body, #mw-content-text {
    background: var(--bg-elevated) !important;
    color: var(--text) !important;
    border-color: var(--border) !important;
  }

  #mw-panel, .vector-menu, #p-logo, .vector-header,
  #left-navigation, #right-navigation, .vector-header-container,
  .vector-pinnable-header, #mw-head {
    background: var(--bg) !important;
    color: var(--text) !important;
  }

  a { color: var(--link) !important; }
  a:visited { color: var(--link-visited) !important; }
  a.new { color: #e06c75 !important; }

  h1, h2, h3, h4, h5, h6 {
    color: var(--text) !important;
    border-color: var(--border) !important;
  }

  table, .wikitable, .infobox, .navbox {
    background: var(--bg-elevated) !important;
    color: var(--text) !important;
    border-color: var(--border) !important;
  }
  .wikitable th, .infobox th, .navbox th {
    background: var(--bg-input) !important;
  }

  input, textarea, select {
    background: var(--bg-input) !important;
    color: var(--text) !important;
    border-color: var(--border) !important;
  }

  /* dial down bright icon/screenshot glare without fully inverting art */
  img { filter: brightness(.9) contrast(1.05); }
  /* expandable/collapsible section bars - override their inline light-blue background */
  .NavHead, .NavFrame .NavHead,
  .navbox-title, .navbox-abovebelow,
  .mw-collapsible-toggle, .collapseButton,
  .toccolours {
    background: #2b3038 !important;
    background-color: #2b3038 !important;
    color: #ffffff !important;
    border-color: var(--border) !important;
  }
  .NavHead a, .navbox-title a, .toccolours a {
    color: #ffffff !important;
  }

  /* darken the overall gray background further */
  html, body {
    background: #121417 !important;
  }
  #content, .mw-body, #bodyContent, .mw-body-content,
  .vector-body, #mw-content-text {
    background: #17191d !important;
  }
}
